CREATE OR REPLACE FUNCTION public.rm_enqueue(p_inspection_id uuid,p_event_type text,p_data jsonb DEFAULT '{}',p_photos jsonb DEFAULT '[]') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.inspections; r public.inspection_external_references; eid text:='hi_evt_'||gen_random_uuid()::text; result uuid; BEGIN
 SELECT * INTO i FROM public.inspections WHERE id=p_inspection_id;
 IF i.market IS DISTINCT FROM 'CL' OR i.inspection_type IS DISTINCT FROM 'captacion' THEN RETURN NULL; END IF;
 SELECT * INTO r FROM public.inspection_external_references WHERE inspection_id=i.id AND provider='rent_manager' AND (is_active OR (i.rm_rescheduled_to IS NOT NULL AND p_event_type='inspection.rescheduled')) ORDER BY is_active DESC,created_at DESC LIMIT 1;
 IF r.id IS NULL OR NULLIF(r.metadata->>'rm_inspection_id','') IS NULL THEN RETURN NULL; END IF;
 INSERT INTO public.rent_manager_outbox(inspection_id,rm_inspection_id,external_object_id,event_id,event_type,payload,photo_objects) VALUES(i.id,r.metadata->>'rm_inspection_id',r.external_object_id,eid,p_event_type,jsonb_build_object('source','homie_inspection','event_id',eid,'event_type',p_event_type,'inspection_id',r.metadata->>'rm_inspection_id','external_object_id',r.external_object_id,'status',i.status,'data',p_data,'at',clock_timestamp()),p_photos) RETURNING id INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.rm_transfer_reference() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NEW.provider='rent_manager' AND NEW.metadata ? 'previous_hi_inspection_id' THEN UPDATE public.inspection_external_references SET is_active=false WHERE inspection_id=(NEW.metadata->>'previous_hi_inspection_id')::uuid AND provider='rent_manager' AND external_object_id=NEW.external_object_id AND is_active; END IF; RETURN NEW; END $$;
CREATE TRIGGER rm_transfer_reference BEFORE INSERT ON public.inspection_external_references FOR EACH ROW EXECUTE FUNCTION public.rm_transfer_reference();
REVOKE ALL ON FUNCTION public.rm_transfer_reference() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.rm_inspection_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.profiles; e public.profiles; ov jsonb; prev jsonb; BEGIN
 ov:=COALESCE(NEW.property_snapshot_json,'{}')||COALESCE(NEW.property_overrides_json,'{}'); prev:=COALESCE(OLD.property_snapshot_json,'{}')||COALESCE(OLD.property_overrides_json,'{}');
 IF (NEW.inspector_id,NEW.executive_id) IS DISTINCT FROM (OLD.inspector_id,OLD.executive_id) AND NEW.inspector_id IS NOT NULL AND NEW.executive_id IS NOT NULL THEN SELECT * INTO a FROM public.profiles WHERE id=NEW.inspector_id; SELECT * INTO e FROM public.profiles WHERE id=NEW.executive_id; PERFORM public.rm_enqueue(NEW.id,'inspection.created',jsonb_build_object('inspector_email',a.email,'inspector_name',a.full_name,'executive_email',e.email,'executive_name',e.full_name)); END IF;
 IF ov->>'keys_status' IS DISTINCT FROM prev->>'keys_status' AND ov->>'keys_status' IS NOT NULL THEN PERFORM public.rm_enqueue(NEW.id,'inspection.keys_updated',jsonb_strip_nulls(jsonb_build_object('tenencia',CASE WHEN ov->>'keys_status'='administracion' THEN 'administracion_edificio' ELSE ov->>'keys_status' END,'detalle',ov->>'keys_detail'))); END IF;
 IF NEW.owner_feedback_status IS DISTINCT FROM OLD.owner_feedback_status THEN PERFORM public.rm_enqueue(NEW.id,'inspection.owner_feedback',jsonb_build_object('owner_feedback_status',NEW.owner_feedback_status)); END IF;
 IF NEW.status IS DISTINCT FROM OLD.status THEN
 IF NEW.status='sent' AND NEW.rm_rescheduled_to IS NULL THEN PERFORM public.rm_enqueue(NEW.id,'inspection.finalized',jsonb_build_object('quien_repara',NEW.quien_repara));
 ELSIF NEW.status='submitted' THEN PERFORM public.rm_enqueue(NEW.id,'inspection.submitted',jsonb_build_object('fecha_de_recepcion',COALESCE(ov->>'fecha_de_recepcion',ov->>'fecha_recepcion',to_char(COALESCE(NEW.inspection_completed_at,NEW.completed_at,now()) AT TIME ZONE 'America/Santiago','YYYY-MM-DD'))));
 ELSIF NEW.status NOT IN ('published','assigned','sent') THEN PERFORM public.rm_enqueue(NEW.id,'inspection.status_changed'); END IF;
 ELSIF NEW.quien_repara IS DISTINCT FROM OLD.quien_repara THEN PERFORM public.rm_enqueue(NEW.id,'inspection.status_changed'); END IF; RETURN NEW; END $$;